import {makeRack} from './war-rack-core.js';
const low=[['Trap','Dark Atlanta',3,.18,2,140],['Drill','Sliding 808',2.5,.15,1.8,120],['Trap','Rage',5,.25,2.5,110],['Trap','Melodic',2,.10,1.6,180],['Amapiano','Log Drum',2,.1,1.5,200],['R&B','Round Sub',1.5,.08,1.5,220]];
export const DRUM_RACKS=[...low.map(([genre,name,drive,mix,ratio,release],i)=>makeRack('war808-'+i,'WAR 808 / '+name,genre,genre==='Amapiano'?'Log Drum':'808','mix',[['sculpt',{highpass:20,cutoff:20000}],['vectoreq',{g0:0,g2:-1}],['circuitcolor',{drive,mix}],['vectorcomp',{threshold:-16,ratio,attack:28,release,mix:.65}]],'Dry low-end processing. Confirm tuning, phase and headroom with kick.')), ...['Trap','Drill','Afrobeat','Rock','Rumba','Amapiano','Pop','R&B'].flatMap((genre,i)=>['Drums','Percussion'].map((source,j)=>makeRack('drum-'+i+'-'+j,genre.toUpperCase()+' / '+source,genre,source,'mix',[['sculpt',{highpass:j?55:25,cutoff:20000}],['circuiteq',{body:j?-.5:.5,presence:1}],['vectorcomp',{threshold:-18,ratio:1.6+(i%3)*.4,attack:30,release:130+i*10,mix:.7}],['circuitcolor',{drive:2,mix:.1}]],'Keep transients; verify kick and bass balance.')))];
